"""Shared code for the sparring bots (eval/bots/spar/<name>/bot.py). Rule-based, no training, standard library only.

Everything a bot needs to play well, so a bot file is only its style:
  - the protocol loop, both legs; stdout carries protocol replies only, debug goes to stderr; no files, network or
    processes; every reply is legal; one decision takes a few ms (equity is capped at 6 ms);
  - an evaluator written for this repo (checked against shared/evaluator.py on 20,000 random pairs of hands);
  - preflop: a table of all 1,755 distinct 3-card starting hands (equity against a random 3-card hand, both keeping
    the best pair, 5,000 deals each) and its percentile; a heads-up preflop policy driven by percentile thresholds;
  - postflop: Monte Carlo equity against the opponent's likely range, not a random hand: samples are weighted by
    their current strength raised to a pressure (what the opponent has bet, raised or called this hand, scaled by how
    often this opponent bets at all), and by whether keeping that pair was consistent with the card they threw
    (the discard is exposed);
  - a discard chosen by equity (common random numbers over the three choices);
  - per-leg opponent counters: how often they fold to our bets, call them, bet when checked to, bet preflop.
A bot subclasses BaseBot and overrides small hooks (parameters P, bet sizing, the first look at a decision).
Cards: c = rank * 4 + suit, ranks "23456789TJQKA", suits "shdc".
"""
import itertools
import json
import os
import random
import sys
import time

RANKS = "23456789TJQKA"
SUITS = "shdc"


def card_to_int(s):
    return RANKS.index(s[0]) * 4 + SUITS.index(s[1])


def int_to_card(c):
    return RANKS[c >> 2] + SUITS[c & 3]


def log(*a):
    print(*a, file=sys.stderr, flush=True)


# ---------------------------------------------------------------- hand scores (own evaluator)
POP = [bin(m).count("1") for m in range(8192)]
STR = [-1] * 8192                       # straight top rank of a rank mask, -1 if none (wheel = 3)
for _m in range(8192):
    for _top in range(12, 3, -1):
        _need = 31 << (_top - 4)
        if _m & _need == _need:
            STR[_m] = _top
            break
    else:
        if _m & 0x100F == 0x100F:
            STR[_m] = 3


def _pack(ranks):
    v = 0
    for r in ranks:
        v = (v << 4) | r
    return v


def score(cards):
    """Best 5-card score of 5-7 cards; a bigger number is a better hand."""
    rc = [0] * 13
    sm = [0, 0, 0, 0]
    for c in cards:
        r = c >> 2
        rc[r] += 1
        sm[c & 3] |= 1 << r
    allm = sm[0] | sm[1] | sm[2] | sm[3]
    fm = 0
    for m in sm:
        if POP[m] >= 5:
            fm = m
    if fm:
        t = STR[fm]
        if t >= 0:
            return (8 << 20) | t
    quads, trips, pairs = [], [], []
    for r in range(12, -1, -1):
        n = rc[r]
        if n == 4:
            quads.append(r)
        elif n == 3:
            trips.append(r)
        elif n == 2:
            pairs.append(r)
    if quads:
        q = quads[0]
        return (7 << 20) | (q << 4) | max(r for r in range(13) if rc[r] and r != q)
    if trips and (len(trips) > 1 or pairs):
        return (6 << 20) | (trips[0] << 4) | max(trips[1:] + pairs)
    if fm:
        return (5 << 20) | _pack([r for r in range(12, -1, -1) if fm >> r & 1][:5])
    t = STR[allm]
    if t >= 0:
        return (4 << 20) | t
    if trips:
        k = [r for r in range(12, -1, -1) if rc[r] and r != trips[0]][:2]
        return (3 << 20) | (trips[0] << 8) | _pack(k)
    if len(pairs) >= 2:
        a, b = pairs[0], pairs[1]
        return (2 << 20) | (a << 8) | (b << 4) | max(r for r in range(13) if rc[r] and r != a and r != b)
    if pairs:
        k = [r for r in range(12, -1, -1) if rc[r] and r != pairs[0]][:3]
        return (1 << 20) | (pairs[0] << 12) | _pack(k)
    return _pack([r for r in range(12, -1, -1) if rc[r]][:5])


def category(sc):
    return sc >> 20


def best_score(hole, board):
    """Score with 2 kept cards, or the best pair of 3 cards (before the discard)."""
    if len(hole) == 2:
        return score(hole + board)
    a, b, c = hole
    return max(score([a, b] + board), score([a, c] + board), score([b, c] + board))


